{"tiddlers":{"$:/plugins/huwiki/trim/startup.js":{"title":"$:/plugins/huwiki/trim/startup.js","type":"application/javascript","module-type":"startup","text":"/* HUWiki Trim 0.1.5 — independent implementation inspired by TW_Tones' Trim.
 * Original Trim code has not been copied. MIT licence (HUWiki implementation).
 * Installed as a standard TiddlyWiki startup module.
 */
(function () {
"use strict";

exports.name = "huwiki-trim-startup";
exports.platforms = ["browser"];
exports.after = ["render"];
exports.synchronous = true;

// Ordinary wiki stylesheet, deliberately not bundled inside the plugin.
// HUWiki synchronizes this $:/plugins/ namespace, while TiddlyWiki
// keeps this standalone tiddler after the editor plugin is disabled/deleted.
var PUBLISHED = "$:/plugins/huwiki/trim-design.css";
var SETTINGS_FIELD = "huwiki-trim-settings";
var SHARED = "$:/plugins/huwiki/trim/shared-design"; // legacy 0.1.x source
var STYLE_ID = "huwiki-trim-runtime-style";
var MARKER = "huw-trim-panel";
var FIELDS = [
  {key:"pageMargin",label:"Sidemargener",group:"layout",unit:"px",min:0,max:70,step:2,initial:20,
    help:"Luft langs wikiens venstre og højre kant."},
  {key:"storyWidth",label:"Indholdets bredde",group:"layout",unit:"px",min:550,max:1250,step:25,initial:850,
    help:"Hvor bredt indholdet vises."},
  {key:"tiddlerPadding",label:"Indvendig afstand",group:"layout",unit:"px",min:8,max:56,step:2,initial:28,
    help:"Luft inde i hver tiddler."},
  {key:"tiddlerGap",label:"Afstand mellem tiddlere",group:"layout",unit:"px",min:0,max:48,step:2,initial:16,
    help:"Plads mellem åbne tiddlere."},
  {key:"cornerRadius",label:"Afrundede hjørner",group:"layout",unit:"px",min:0,max:32,step:1,initial:8,
    help:"Fra skarpe til bløde hjørner."},
  {key:"stickyTitles",label:"Fastgør tiddlertitler",type:"toggle",min:0,max:1,step:1,initial:0,
    help:"Behold titler og tilhørende værktøjer synlige under rulning."},
  {key:"stickyOffset",label:"Afstand fra toppen",group:"sticky",unit:"px",min:0,max:100,step:2,initial:0,
    help:"Hvor langt under toppen den fastgjorte titel placeres."},
  {key:"titleSize",label:"Tiddlertitler",group:"typography",unit:"px",min:18,max:46,step:1,initial:29,
    help:"Størrelsen på tiddlernes titler."},
  {key:"bodySize",label:"Brødtekst",group:"typography",unit:"px",min:12,max:24,step:1,initial:16,
    help:"Skriftstørrelse i indholdet."},
  {key:"bodyLineHeight",label:"Linjeafstand",group:"typography",unit:"%",min:110,max:210,step:5,initial:155,
    help:"Luft mellem tekstlinjer."}
];
var FIELD_MAP = {};
FIELDS.forEach(function(f){FIELD_MAP[f.key]=f;});
var PRESETS = {
  compact:{pageMargin:8,storyWidth:1100,tiddlerPadding:14,tiddlerGap:8,cornerRadius:3},
  balanced:{pageMargin:20,storyWidth:850,tiddlerPadding:28,tiddlerGap:16,cornerRadius:8},
  roomy:{pageMargin:36,storyWidth:900,tiddlerPadding:40,tiddlerGap:30,cornerRadius:18}
};

function defined(obj,key) {return Object.prototype.hasOwnProperty.call(obj,key);}
function clean(raw) {
  var obj = raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
  var out = {};
  FIELDS.forEach(function(f) {
    if(!defined(obj,f.key)) return;
    var value=Number(obj[f.key]);
    if(!Number.isFinite(value)) return;
    value=Math.min(f.max,Math.max(f.min,Math.round(value/f.step)*f.step));
    out[f.key]=value;
  });
  return out;
}
function combine(base,overrides) {return Object.assign({},clean(base),clean(overrides));}
function difference(current,base) {
  var a=clean(current), b=clean(base), result={};
  Object.keys(a).forEach(function(key){if(!defined(b,key)||a[key]!==b[key])result[key]=a[key];});
  return result;
}
function equalSettings(first,second) {
  var a=clean(first),b=clean(second);
  return FIELDS.every(function(f){
    var inA=defined(a,f.key),inB=defined(b,f.key);
    return inA===inB && (!inA || a[f.key]===b[f.key]);
  });
}
function cssFor(settings,stronger,guarded) {
  // Published CSS is independent of Trim. While previewing, a temporary
  // document attribute suppresses *only* this stylesheet, so resetting a
  // slider immediately reveals the active theme underneath.
  var selectorPrefix=stronger?"html:root:root ":
    (guarded?"html:not([data-huwiki-trim-preview]) ":"");
  var s=clean(settings),rules=[];
  function css(selector,declaration){rules.push(selectorPrefix+selector+"{"+declaration+"}");}
  function has(k){return defined(s,k);}
  // Each rule is conditional: install alone never changes the theme.
  if(has("pageMargin"))css(".tc-page-container","padding-left:"+s.pageMargin+"px!important;padding-right:"+s.pageMargin+"px!important");
  if(has("storyWidth"))css(".tc-story-river","max-width:min(100%,"+s.storyWidth+"px)!important");
  if(has("tiddlerPadding"))css(".tc-story-river .tc-tiddler-frame","padding:"+s.tiddlerPadding+"px!important");
  if(has("tiddlerGap"))css(".tc-story-river .tc-tiddler-frame","margin-bottom:"+s.tiddlerGap+"px!important");
  if(has("cornerRadius"))css(".tc-story-river .tc-tiddler-frame","border-radius:"+s.cornerRadius+"px!important");
  if(s.stickyTitles===1)css(".tc-story-river .tc-tiddler-frame .tc-tiddler-title","position:sticky!important;top:"+(s.stickyOffset||0)+"px!important;z-index:5");
  if(has("titleSize"))css(".tc-story-river .tc-tiddler-frame .tc-title","font-size:"+s.titleSize+"px!important");
  if(has("bodySize"))css(".tc-story-river .tc-tiddler-body","font-size:"+s.bodySize+"px!important");
  if(has("bodyLineHeight"))css(".tc-story-river .tc-tiddler-body","line-height:"+(s.bodyLineHeight/100).toFixed(2)+"!important");
  return rules.join("\n");
}
function readJSON(text){try{return JSON.parse(text);}catch(ignore){return {};}}
function storageKey(wiki){
  var id=String(wiki.getTiddlerText("$:/Wiki/CurrentWikiId")||"").trim();
  // Apps Script hosts many wikis at one origin: never use a single global key.
  if(!id && typeof location!=="undefined")id=location.origin+location.pathname+location.search;
  return "huwiki.trim.local.v1:"+encodeURIComponent(id||"untitled");
}
function isReader(wiki){
  return wiki.getTiddlerText("$:/temp/wiki/access/role")==="reader" ||
    wiki.getTiddlerText("$:/HUWiki/ReaderEnabled")==="yes";
}
function publishedDesign(wiki){
  return wiki.getTiddler(PUBLISHED);
}
function readShared(wiki){
  var published=publishedDesign(wiki);
  if(published && published.fields && typeof published.fields[SETTINGS_FIELD]==="string"){
    // The independent stylesheet carries its own editable slider values.
    return clean(readJSON(published.fields[SETTINGS_FIELD]));
  }
  // Backward compatibility: users of v0.1.1–v0.1.3 keep the old design
  // until the first save publishes an independent stylesheet.
  var old=wiki.getTiddler(SHARED);
  return clean(old ? readJSON(old.fields.text||"{}") : {});
}
function designSignature(wiki){
  var p=publishedDesign(wiki);
  return p && p.fields ? "published:"+JSON.stringify(p.fields) :
    "legacy:"+(wiki.getTiddlerText(SHARED)||"");
}
function independentStyleFields(wiki,values){
  var now=new Date();
  return {
    title:PUBLISHED,
    type:"text/css",
    tags:["$:/tags/Stylesheet"],
    text:cssFor(values,false,true),
    "huwiki-trim-settings":JSON.stringify(clean(values)),
    "huwiki-trim-format":"1",
    modified:$tw.utils.stringifyDate(now),
    modifier:wiki.getTiddlerText("$:/status/UserName")||""
  };
}
function readLocal(key){try{return clean(readJSON(localStorage.getItem(key)||"{}"));}catch(ignore){return {};}}
function writeLocal(key,obj){
  try {
    if(Object.keys(obj).length)localStorage.setItem(key,JSON.stringify(clean(obj)));
    else localStorage.removeItem(key);
    return true;
  } catch(ignore){return false;}
}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,function(x){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[x];});}

function readProfiles(key) {
  try {
    var raw=JSON.parse(localStorage.getItem(key)||"[]");
    if(!Array.isArray(raw))return [];
    return raw.slice(0,12).filter(function(p){return p&&typeof p.name==="string"&&p.name.trim();})
      .map(function(p){return {name:p.name.trim().slice(0,48),values:clean(p.values)};});
  }catch(ignore){return [];}
}
function writeProfiles(key,profiles) {
  try {localStorage.setItem(key,JSON.stringify(profiles.slice(0,12)));return true;}
  catch(ignore){return false;}
}

exports.startup = function() {
  if(typeof document==="undefined" || typeof $tw==="undefined" || !$tw.wiki)return;
  var wiki=$tw.wiki,reader=isReader(wiki),key=storageKey(wiki);
  var shared=readShared(wiki),local=reader?readLocal(key):{},working=null,dirty=false,touched={},
      observedSignature=designSignature(wiki),savingShared=false;
  var profileKey=key+":profiles",profiles=readProfiles(profileKey);
  var cssNode=document.getElementById(STYLE_ID);
  if(!cssNode){cssNode=document.createElement("style");cssNode.id=STYLE_ID;document.head.appendChild(cssNode);}
  function base(){return reader?combine(shared,local):clean(shared);}
  function refreshStyle(){
    var current=dirty&&working?working:base();
    // A dirty draft temporarily replaces the published layer rather than
    // competing with it. The attribute is removed on save/cancel.
    if(publishedDesign(wiki) && dirty)document.documentElement.setAttribute("data-huwiki-trim-preview","");
    else document.documentElement.removeAttribute("data-huwiki-trim-preview");
    if(!publishedDesign(wiki)){
      // Migrated pre-0.1.4 wiki: continue the legacy runtime until published.
      cssNode.textContent=cssFor(current);
    }else if(dirty){
      // Live preview overlays the independent shared stylesheet.
      cssNode.textContent=cssFor(current,true);
    }else if(reader){
      // The shared CSS needs no JavaScript; only the reader's own overrides do.
      cssNode.textContent=cssFor(local,true);
    }else{
      // Editors see the published CSS, and the plugin contributes no CSS.
      cssNode.textContent="";
    }
  }
  function info(panel,msg,error){
    var element=panel.querySelector(".huw-trim-status");
    if(element){element.textContent=msg;element.setAttribute("data-error",error?"yes":"no");}
  }
  function updateValues(panel,settings){
    FIELDS.forEach(function(f){
      var explicit=defined(settings,f.key),v=explicit?settings[f.key]:f.initial;
      var input=panel.querySelector('input[data-trim-key="'+f.key+'"]');
      if(!input)return;
      if(f.type==="toggle")input.checked=Boolean(v);
      else input.value=v;
      var output=panel.querySelector('output[data-trim-key="'+f.key+'"]');
      if(output)output.textContent=explicit?String(v)+f.unit:"";
      var reset=panel.querySelector('button[data-trim-reset-key="'+f.key+'"]');
      if(reset){
        var modified=reader?
          (dirty&&touched[f.key]==="inherit"?false:
            defined(local,f.key)||(dirty&&touched[f.key]==="value")):
          explicit;
        reset.disabled=!modified;
      }
    });
    panel.querySelectorAll('[data-trim-preset]').forEach(function(button){
      var values=PRESETS[button.getAttribute('data-trim-preset')];
      var selected=Object.keys(values).every(function(k){return settings[k]===values[k];});
      button.setAttribute('aria-pressed',selected?'true':'false');
    });
  }
  function setPanelMode(panel){
    var button=panel.querySelector('.huw-trim-save');
    button.textContent=reader?'Husk min visning':'Gem fælles visning';
    button.title=reader?'Gem kun i denne browser':'Gem som wikiens fælles design';
    panel.querySelector('.huw-trim-reset').textContent=reader?'Nulstil min visning':'Fortryd prøve';
    FIELDS.forEach(function(f){
      var b=panel.querySelector('button[data-trim-reset-key="'+f.key+'"]');
      if(!b)return;
      var label=(reader?'Brug fælles visning for ':'Brug temaets standard for ')+f.label.toLowerCase();
      b.title=label;b.setAttribute('aria-label',label);
    });
  }
  function redrawPanels(){
    var values=dirty&&working?working:base();
    document.querySelectorAll('.'+MARKER+'[data-trim-mounted="1"]').forEach(function(panel){
      updateValues(panel,values);
    });
  }
  function fieldMarkup(f){
    var reset='<button type="button" class="huw-trim-field-reset" data-trim-reset-key="'+f.key+'" aria-label="Nulstil '+escapeHTML(f.label)+'" title="Nulstil '+escapeHTML(f.label)+'">↺</button>';
    if(f.type==='toggle')return '<div class="huw-trim-checkbox-row"><label><input type="checkbox" data-trim-key="'+f.key+'"> <span>'+escapeHTML(f.label)+'</span></label>'+reset+'</div>'+
      (f.help?'<p class="huw-trim-help">'+escapeHTML(f.help)+'</p>':'');
    return '<div class="huw-trim-field"><div class="huw-trim-field-head">'+
      '<strong>'+escapeHTML(f.label)+'</strong><div class="huw-trim-field-tools">'+
      '<output data-trim-key="'+f.key+'"></output>'+reset+'</div></div>'+
      '<input type="range" data-trim-key="'+f.key+'" min="'+f.min+'" max="'+f.max+'" step="'+f.step+'" value="'+f.initial+'" aria-label="'+escapeHTML(f.label)+'">'+
      (f.help?'<p class="huw-trim-help">'+escapeHTML(f.help)+'</p>':'')+'</div>';
  }
  function section(label,fields){return '<section class="huw-trim-section"><h3>'+escapeHTML(label)+'</h3>'+fields.map(function(key){return fieldMarkup(FIELD_MAP[key]);}).join('')+'</section>';}
  function switchTab(panel,name){
    panel.querySelectorAll('[data-trim-tab]').forEach(function(tab){
      var active=tab.getAttribute('data-trim-tab')===name;
      tab.setAttribute('aria-selected',active?'true':'false');
      tab.tabIndex=active?0:-1;
    });
    panel.querySelectorAll('[data-trim-page]').forEach(function(page){
      page.hidden=page.getAttribute('data-trim-page')!==name;
    });
    if(name==='saved')renderProfiles(panel);
  }
  function renderProfiles(panel){
    var target=panel.querySelector('.huw-trim-profile-list');
    if(!target)return;
    if(!profiles.length){target.innerHTML='<p class="huw-trim-empty">Der er endnu ingen gemte profiler.</p>';return;}
    target.innerHTML=profiles.map(function(profile,i){
      return '<div class="huw-trim-profile"><span>'+escapeHTML(profile.name)+'</span>'+
        '<button type="button" data-trim-apply-profile="'+i+'">Brug</button>'+
        '<button type="button" data-trim-delete-profile="'+i+'" aria-label="Slet profil '+escapeHTML(profile.name)+'" title="Slet">×</button></div>';
    }).join('');
  }
  function pendingLocalRemovals(){
    // A locally saved value may match the shared value today but still mask
    // future shared changes. Keep its reset pending until the user saves.
    return reader && Object.keys(touched).some(function(key){
      return touched[key]==="inherit" && defined(local,key);
    });
  }
  function finishPreview(){
    if(dirty && equalSettings(working,base()) && !pendingLocalRemovals()){
      working=null;dirty=false;touched={};
    }
    refreshStyle();redrawPanels();
  }
  function ensurePreview(){
    if(!dirty){working=base();dirty=true;touched={};}
  }
  function rebaseReaderPreview(){
    // Keep the user's actively adjusted values, including explicit per-slider
    // resets, while still inheriting fresh updates to other shared settings.
    if(!reader||!dirty||!working)return;
    var previous=working,rebased=base();
    Object.keys(touched).forEach(function(key){
      if(touched[key]==="inherit"){
        if(defined(shared,key))rebased[key]=shared[key];
        else delete rebased[key];
      } else if(defined(previous,key))rebased[key]=previous[key];
      else delete rebased[key];
    });
    working=rebased;
    if(equalSettings(working,base()) && !pendingLocalRemovals()){
      working=null;dirty=false;touched={};
    }
  }
  function mount(panel){
    if(panel.getAttribute('data-trim-mounted')==='1')return;
    panel.setAttribute('data-trim-mounted','1');
    var html='<header class="huw-trim-brand"><div class="huw-trim-brandname"><span class="huw-trim-brandhu">HUWiki</span> <strong>trim</strong></div><span class="huw-trim-brandnote">Gør plads.</span></header>'+
      '<nav role="tablist" aria-label="Trim indstillinger" class="huw-trim-tabs">'+
      '<button type="button" role="tab" data-trim-tab="layout">Layout</button>'+
      '<button type="button" role="tab" data-trim-tab="sticky">Fastgjort</button>'+
      '<button type="button" role="tab" data-trim-tab="type">Overskrifter</button>'+
      '<button type="button" role="tab" data-trim-tab="saved">Gemte</button></nav>'+
      '<div class="huw-trim-page" role="tabpanel" data-trim-page="layout">'+
      '<div class="huw-trim-presets" role="group" aria-label="Hurtige layoutvalg">'+
      '<button type="button" data-trim-preset="compact">Kompakt</button>'+
      '<button type="button" data-trim-preset="balanced">Afbalanceret</button>'+
      '<button type="button" data-trim-preset="roomy">Luftig</button></div>'+
      section('Sidekanter',['pageMargin','storyWidth'])+
      section('Tiddlere',['tiddlerPadding','tiddlerGap','cornerRadius'])+'</div>'+
      '<div class="huw-trim-page" role="tabpanel" data-trim-page="sticky" hidden>'+section('Fastgjort ved rulning',['stickyTitles','stickyOffset'])+'</div>'+
      '<div class="huw-trim-page" role="tabpanel" data-trim-page="type" hidden>'+section('Overskrifter',['titleSize'])+section('Brødtekst',['bodySize','bodyLineHeight'])+'</div>'+
      '<div class="huw-trim-page" role="tabpanel" data-trim-page="saved" hidden>'+
      '<section class="huw-trim-section"><h3>Gemte udseender</h3><p class="huw-trim-help">Profiler gemmes i denne browser. Brug den almindelige Gem-knap for at dele et valgt design.</p>'+
      '<div class="huw-trim-profile-entry"><input type="text" class="huw-trim-profile-name" maxlength="48" placeholder="Navn på profil" aria-label="Navn på profil">'+
      '<button type="button" class="huw-trim-profile-save">Gem profil</button></div><div class="huw-trim-profile-list"></div></section></div>'+
      '<div class="huw-trim-actions"><button type="button" class="huw-trim-save"></button><button type="button" class="huw-trim-reset"></button></div>'+
      '<p role="status" aria-live="polite" class="huw-trim-status"></p>';
    panel.innerHTML=html;
    setPanelMode(panel);switchTab(panel,'layout');updateValues(panel,dirty&&working?working:base());
    panel.querySelectorAll('button[data-trim-tab]').forEach(function(tab){
      tab.addEventListener('click',function(){switchTab(panel,tab.getAttribute('data-trim-tab'));});
      tab.addEventListener('keydown',function(evt){
        if(evt.key!=='ArrowLeft'&&evt.key!=='ArrowRight')return;
        evt.preventDefault();
        var all=Array.prototype.slice.call(panel.querySelectorAll('button[data-trim-tab]'));
        var i=all.indexOf(tab),next=all[(i+(evt.key==='ArrowRight'?1:-1)+all.length)%all.length];
        switchTab(panel,next.getAttribute('data-trim-tab'));next.focus();
      });
    });
    panel.querySelectorAll('input[data-trim-key]').forEach(function(input){
      input.addEventListener(input.type==='checkbox'?'change':'input',function(){
        ensurePreview();var name=input.getAttribute('data-trim-key');
        working[name]=input.type==='checkbox'?(input.checked?1:0):Number(input.value);
        touched[name]='value';finishPreview();
        info(panel,'Ændringen er endnu ikke gemt.',false);
      });
    });
    panel.querySelectorAll('button[data-trim-reset-key]').forEach(function(button){
      button.addEventListener('click',function(){
        var name=button.getAttribute('data-trim-reset-key');ensurePreview();
        if(reader&&defined(shared,name))working[name]=shared[name];
        else delete working[name];
        touched[name]='inherit';finishPreview();
        info(panel,dirty?'Nulstillet – gem for at bevare ændringen.':'Standardvisningen bruges nu.',false);
      });
    });
    panel.querySelectorAll('button[data-trim-preset]').forEach(function(button){
      button.addEventListener('click',function(){
        ensurePreview();
        var values=PRESETS[button.getAttribute('data-trim-preset')];
        Object.keys(values).forEach(function(k){working[k]=values[k];touched[k]='value';});
        finishPreview();info(panel,'Layoutet er valgt. Gem, hvis det skal bevares.',false);
      });
    });
    panel.querySelector('.huw-trim-profile-save').addEventListener('click',function(){
      var name=panel.querySelector('.huw-trim-profile-name').value.trim().slice(0,48);
      if(!name){info(panel,'Skriv et navn til profilen.',true);return;}
      var current=clean(dirty&&working?working:base());
      var next=profiles.filter(function(p){return p.name.toLowerCase()!==name.toLowerCase();});
      next.unshift({name:name,values:current});next=next.slice(0,12);
      if(!writeProfiles(profileKey,next)){info(panel,'Browseren tillader ikke lokal lagring af profiler.',true);return;}
      profiles=next;panel.querySelector('.huw-trim-profile-name').value='';
      document.querySelectorAll('.'+MARKER+'[data-trim-mounted="1"]').forEach(renderProfiles);
      info(panel,'Profil gemt i denne browser.',false);
    });
    panel.querySelector('.huw-trim-profile-list').addEventListener('click',function(event){
      var button=event.target.closest('button');if(!button)return;
      var load=button.getAttribute('data-trim-apply-profile');
      var remove=button.getAttribute('data-trim-delete-profile');
      if(load!==null){
        var profile=profiles[Number(load)];if(!profile)return;
        ensurePreview();working=clean(profile.values);
        FIELDS.forEach(function(f){touched[f.key]=defined(working,f.key)?'value':'inherit';});
        finishPreview();info(panel,'Profilen er taget i brug. Gem for at beholde visningen.',false);
      }else if(remove!==null){
        var next=profiles.filter(function(p,i){return i!==Number(remove);});
        if(!writeProfiles(profileKey,next)){info(panel,'Kunne ikke slette profilen.',true);return;}
        profiles=next;document.querySelectorAll('.'+MARKER+'[data-trim-mounted="1"]').forEach(renderProfiles);
        info(panel,'Profilen er slettet.',false);
      }
    });
    panel.querySelector('.huw-trim-save').addEventListener('click',function(){
      if(!dirty){
        if(!reader && !publishedDesign(wiki) && Object.keys(shared).length){
          // One-click migration: promote v0.1.1–0.1.3 saved design to
          // independent stylesheet without forcing the user to move a slider.
          ensurePreview();
        } else {info(panel,'Der er ingen nye ændringer.',false);return;}
      }
      if(reader){
        var changes=difference(working,shared);
        if(!writeLocal(key,changes)){info(panel,'Browseren tillader ikke lokal lagring. Visningen er kun midlertidig.',true);return;}
        local=changes;working=null;dirty=false;touched={};refreshStyle();redrawPanels();
        info(panel,'Din visning er husket i denne browser – ikke i wikien.',false);return;
      }
      if(designSignature(wiki)!==observedSignature){
        info(panel,'Det fælles design er ændret af en anden. Vælg Fortryd prøve og prøv igen.',true);return;
      }
      var existing=publishedDesign(wiki);
      if(existing){
        var stored=existing.fields||{},settings=stored[SETTINGS_FIELD],expected="";
        if(typeof settings!=="string"){
          info(panel,'Den fælles CSS mangler Trim-indstillinger. Undersøg stilarket før overskrivning.',true);return;
        }
        expected=cssFor(clean(readJSON(settings)),false,true);
        if(stored.text!==expected){
          info(panel,'Designets CSS er redigeret uden for Trim. Den bliver ikke overskrevet.',true);return;
        }
      }
      try{
        var values=clean(working);
