.huw-trim-panel{
  --ht-ink:#263448;--ht-muted:#657181;--ht-line:#dfe3e9;
  --ht-blue:#3465ad;--ht-blue-soft:#eaf0fa;--ht-surface:#fff;
  box-sizing:border-box;min-width:0;max-width:560px;width:100%;
  margin:0;padding:6px 8px 16px;background:var(--ht-surface);
  color:var(--ht-ink);font:13px/1.4 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}
.huw-trim-panel *, .huw-trim-panel *::before,.huw-trim-panel *::after{box-sizing:border-box}
.huw-trim-brand{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin:1px 0 14px}
.huw-trim-brandname{display:flex;align-items:baseline;gap:4px;white-space:nowrap}
.huw-trim-brandhu{font-size:11px;letter-spacing:.075em;font-weight:800;color:#315389;text-transform:uppercase}
.huw-trim-brandname strong{font-size:27px;line-height:1.0;letter-spacing:-.07em;font-weight:850;color:var(--ht-blue)}
.huw-trim-brandnote{font-size:11px;color:var(--ht-muted);white-space:nowrap}
.huw-trim-checkbox-row{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:34px}
.huw-trim-checkbox-row label{display:flex;align-items:center;gap:6px;min-width:0;font-size:13px;font-weight:660;cursor:pointer}
.huw-trim-checkbox-row input[type=checkbox]{width:17px;height:17px;margin:0;accent-color:#2985da;cursor:pointer}
.huw-trim-tabs{display:flex;align-items:stretch;gap:3px;overflow-x:auto;white-space:nowrap;max-width:100%;margin-bottom:12px;padding-bottom:1px;scrollbar-width:thin}
.huw-trim-tabs button{flex:1 0 auto;min-width:0;margin:0;border:1px solid #dadde3;border-bottom:2px solid #d2d8e0;border-radius:5px 5px 0 0;background:#f1f2f4;color:#555f6c;padding:8px 8px 7px;font:650 11px/1.25 system-ui,sans-serif;cursor:pointer}
.huw-trim-tabs button[aria-selected=true]{color:var(--ht-blue);border-color:#cfd7e5;border-bottom-color:var(--ht-blue);background:var(--ht-surface)}
.huw-trim-tabs button:hover{color:var(--ht-blue)}
.huw-trim-page[hidden]{display:none!important}
.huw-trim-presets{display:flex;flex-wrap:wrap;gap:6px;margin:9px 0 16px}
.huw-trim-presets button{border:1px solid #d4d9e0;border-radius:5px;background:var(--ht-surface);color:var(--ht-ink);font:650 11px/1.3 system-ui,sans-serif;padding:9px 10px;cursor:pointer;min-height:34px}
.huw-trim-presets button[aria-pressed=true]{border-color:var(--ht-blue);color:var(--ht-blue);background:var(--ht-blue-soft)}
.huw-trim-section{margin:6px 0 17px}
.huw-trim-section h3{border-bottom:1px solid var(--ht-line);margin:0 0 11px;padding:1px 0 7px;text-transform:uppercase;letter-spacing:.065em;color:var(--ht-ink);font:750 11px/1.3 system-ui,sans-serif}
.huw-trim-field{margin:0 0 13px;min-width:0}
.huw-trim-field-head{display:flex;align-items:center;justify-content:space-between;gap:5px;min-height:30px}
.huw-trim-field-head strong{color:var(--ht-ink);font-size:12px;font-weight:650;line-height:1.2}
.huw-trim-field-tools{display:flex;align-items:center;justify-content:flex-end;gap:2px;flex-shrink:0;min-width:46px}
.huw-trim-field output{font:750 12px/1.2 system-ui,sans-serif;color:var(--ht-blue);font-variant-numeric:tabular-nums;white-space:nowrap}
.huw-trim-field-reset{display:grid;place-items:center;flex:0 0 27px;width:27px;height:27px;margin:0;padding:0;border:0;border-radius:5px;background:transparent;color:var(--ht-blue);font:400 20px/1 system-ui,sans-serif;cursor:pointer}
.huw-trim-field-reset:hover:not(:disabled){background:var(--ht-blue-soft)}
.huw-trim-field-reset:disabled{opacity:.22;cursor:default}
.huw-trim-field input[type=range]{display:block;width:100%;height:19px;margin:2px 0 1px;accent-color:var(--ht-blue);touch-action:pan-y;cursor:pointer}
.huw-trim-help{color:var(--ht-muted);font-size:10.5px;line-height:1.35;margin:3px 0 5px}
.huw-trim-page .huw-trim-checkbox-row{border:0;margin-top:2px}
.huw-trim-profile-entry{display:flex;gap:6px;margin:12px 0 10px}
.huw-trim-profile-entry input{min-width:0;flex:1 1 50%;height:37px;border-radius:5px;border:1px solid #cbd4df;background:var(--ht-surface);padding:5px 8px;color:var(--ht-ink);font:inherit}
.huw-trim-profile-entry button,.huw-trim-profile button{border:1px solid #cbd4df;background:var(--ht-surface);color:var(--ht-ink);border-radius:5px;padding:6px 9px;min-height:36px;font:650 11px/1.25 system-ui,sans-serif;cursor:pointer}
.huw-trim-profile-list{display:grid;gap:7px}
.huw-trim-empty{margin:8px 0;color:var(--ht-muted);font-size:12px}
.huw-trim-profile{display:flex;align-items:center;gap:6px;padding:5px 0;border-top:1px solid var(--ht-line)}
.huw-trim-profile span{flex:1 1 auto;min-width:0;overflow-wrap:anywhere}
.huw-trim-profile button:last-child{min-width:32px;font-size:18px;color:#9f4d4d}
.huw-trim-actions{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0 4px;padding:12px 0 0;border-top:1px solid var(--ht-line)}
.huw-trim-actions button{flex:1 1 135px;min-height:42px;border:1px solid #cbd4df;border-radius:6px;background:var(--ht-surface);color:var(--ht-ink);padding:8px 9px;font:650 12px/1.3 system-ui,sans-serif;cursor:pointer}
.huw-trim-actions .huw-trim-save{background:var(--ht-blue);border-color:var(--ht-blue);color:#fff}
.huw-trim-actions button:hover,.huw-trim-profile-entry button:hover,.huw-trim-profile button:hover{filter:brightness(.96)}
.huw-trim-panel button:focus-visible,.huw-trim-panel input:focus-visible{outline:2px solid #7caee9;outline-offset:2px}
.huw-trim-status{font-size:11px;color:#315c46;overflow-wrap:anywhere;margin:7px 0 0}
.huw-trim-status:empty{display:none}
.huw-trim-status[data-error=yes]{color:#a5323d}
@media(hover:none){.huw-trim-field-reset{min-width:44px;min-height:44px;flex-basis:44px}.huw-trim-tabs button,.huw-trim-presets button{min-height:44px}}
@media(prefers-color-scheme:dark){
 .huw-trim-panel{--ht-ink:#e6edf6;--ht-muted:#b0c0d4;--ht-line:#435165;--ht-blue:#9fc6ff;--ht-blue-soft:#2b3c55;--ht-surface:#1c2738}
 .huw-trim-brandhu{color:#bfd6f7}
 .huw-trim-tabs button{background:#2d3a4c;color:#c0cbdb;border-color:#4d5c6f}
 .huw-trim-tabs button[aria-selected=true]{background:var(--ht-surface)}
 .huw-trim-actions .huw-trim-save{background:#376bac;color:#fff;border-color:#376bac}
 .huw-trim-status{color:#9ed8b8}
 .huw-trim-status[data-error=yes]{color:#ffb6be}
}
